def min_cost_to_make_k_equal(arr, n, k):
    # We need to make k elements equal, and we can choose any value
    # The optimal target value will be one of the existing elements in the array
    # For each possible target value, calculate cost to convert k elements to it
    min_cost = float('inf')

    # Try each unique value in the array as target
    unique_vals = set(arr)

    for target in unique_vals:
        cost = 0
        count = 0

        # Count how many elements we can convert to target
        for val in arr:
            if count >= k:
                break
            if val == target:
                count += 1
            else:
                # If val > target, we need to decrement (cost 5 per decrement)
                # If val < target, we need to increment (cost 3 per increment)
                if val > target:
                    cost += (val - target) * 5
                else:
                    cost += (target - val) * 3

        # If we have at least k elements that can be converted to target
        if count >= k:
            # We only need to convert k elements, so we can stop at k elements
            # We'll calculate cost for converting exactly k elements
            cost = 0
            elements_to_convert = 0

            for val in arr:
                if elements_to_convert >= k:
                    break
                if val == target:
                    elements_to_convert += 1
                else:
                    if val > target:
                        cost += (val - target) * 5
                    else:
                        cost += (target - val) * 3

            min_cost = min(min_cost, cost)

    return min_cost

