def time_to_minutes(time_str):
    time_parts = time_str.split()
    time_part = time_parts[0]
    am_pm = time_parts[1]

    hours, minutes = map(int, time_part.split(':'))

    # Convert to 24-hour format
    if am_pm == "AM":
        if hours == 12:
            hours = 0
    else:  # PM
        if hours != 12:
            hours += 12

    return hours * 60 + minutes

def solve():
    P = input().strip()
    N = int(input().strip())

    result = []

    for _ in range(N):
        line = input().strip()
        L, R = line.split()

        P_minutes = time_to_minutes(P)
        L_minutes = time_to_minutes(L)
        R_minutes = time_to_minutes(R)

        if L_minutes <= P_minutes <= R_minutes:
            result.append('1')
        else:
            result.append('0')

    return ''.join(result)

T = int(input().strip())
for _ in range(T):
    print(solve())
